namespace {
class HistoryChart:public QWidget{
public:QJsonArray samples;QString source;QDateTime from,to;HistoryChart(){setMinimumHeight(170);}
protected:void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#292b30"));QRectF r=QRectF(rect()).adjusted(38,18,-12,-28);const qint64 a=from.toSecsSinceEpoch(),b=to.toSecsSinceEpoch();if(b<=a)return;QVector<double> bins(48,-1);double peak=1;for(auto value:samples){const auto sample=value.toObject();if(sample["source"].toString()!=source)continue;qint64 t=sample["time"].toDouble();if(t<a||t>b||!sample.contains("connections"))continue;int i=qBound(0,int((t-a)*48/(b-a)),47);bins[i]=qMax(bins[i],sample["connections"].toDouble());peak=qMax(peak,bins[i]);}const double tick=qMax(1.,std::ceil(peak/4));peak=tick*4;p.setPen(QColor("#555961"));for(int i=0;i<=4;++i){double y=r.bottom()-r.height()*i/4;p.drawLine(QPointF(r.left(),y),QPointF(r.right(),y));p.drawText(QRectF(0,y-8,32,16),Qt::AlignRight,QString::number(qCeil(peak*i/4)));}p.setPen(Qt::NoPen);p.setBrush(QColor("#75a7cf"));for(int i=0;i<48;++i)if(bins[i]>=0)p.drawRoundedRect(QRectF(r.left()+i*r.width()/48,r.bottom()-bins[i]/peak*r.height(),qMax(1.,r.width()/48-2),qMax(1.,bins[i]/peak*r.height())),2,2);p.setPen(QColor("#bbc0c9"));p.drawText(QRectF(r.left(),r.bottom()+6,r.width()/2,18),from.toString("dd MMM HH:mm"));p.drawText(QRectF(r.center().x(),r.bottom()+6,r.width()/2,18),Qt::AlignRight,to.toString("dd MMM HH:mm"));if(std::none_of(bins.cbegin(),bins.cend(),[](double value){return value>=0;}))p.drawText(r,Qt::AlignCenter,"No recorded audience samples in this period");}
};
}
QWidget *studioDashboard(Playout *play){
    auto *page=new QWidget;auto *layout=new QVBoxLayout(page);layout->setContentsMargins(10,10,10,10);auto *title=new QLabel("BROADCAST MONITOR");layout->addWidget(title);auto *stateLabel=new QLabel;layout->addWidget(stateLabel);QObject::connect(play,&Playout::stateChanged,page,[=]{stateLabel->setText(play->state()==Playout::Playing?"Playout running":play->state()==Playout::Paused?"Playout paused":"Playout stopped");});stateLabel->setText("Playout stopped");
    auto *count=new QLabel("Audience source disconnected");count->setStyleSheet("font-size:18px;color:#a7c9e7;");layout->addWidget(count);auto *note=new QLabel("Receiver connections are measured by your MediaMTX server. They are not unique people or satellite/cable audience estimates. Times below are UTC.");note->setWordWrap(true);layout->addWidget(note);
    auto *form=new QFormLayout;auto *url=new QLineEdit(QSettings().value("monitor/url","http://127.0.0.1:9998/metrics").toString());auto *path=new QLineEdit(QSettings().value("monitor/path","cuebase").toString());form->addRow("Metrics URL",url);form->addRow("Stream path",path);layout->addLayout(form);auto *connectButton=new QPushButton(uiIcon("world"),"Connect metrics");connectButton->setCheckable(true);layout->addWidget(connectButton);
    auto *local=new QPushButton(uiIcon("play"),"Start local test receiver");layout->addWidget(local);auto *destinations=new QLabel("Local test destinations\nRTMP: rtmp://127.0.0.1:1935/cuebase\nSRT: srt://127.0.0.1:8890?streamid=publish:cuebase\nWatch: http://127.0.0.1:8888/cuebase");destinations->setTextInteractionFlags(Qt::TextSelectableByMouse);destinations->setWordWrap(true);layout->addWidget(destinations);
    auto *period=new QComboBox;period->addItems({"Today","This week","Last month","Custom range"});layout->addWidget(period);auto *dates=new QHBoxLayout;auto *from=new QDateTimeEdit,*to=new QDateTimeEdit;for(auto *date:{from,to}){date->setTimeZone(QTimeZone::UTC);date->setDisplayFormat("yyyy-MM-dd HH:mm");date->setCalendarPopup(true);}dates->addWidget(from);dates->addWidget(to);layout->addLayout(dates);auto *chart=new HistoryChart;layout->addWidget(chart);auto *summary=new QLabel;summary->setWordWrap(true);layout->addWidget(summary);auto *status=new QLabel;status->setWordWrap(true);layout->addWidget(status);layout->addStretch();
    const QString directory=QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);QDir().mkpath(directory);const QString historyFile=directory+"/broadcast-metrics.json";QFile file(historyFile);if(file.open(QIODevice::ReadOnly))chart->samples=QJsonDocument::fromJson(file.readAll()).array();
    auto update=[=]{chart->source=url->text().trimmed()+"|"+path->text().trimmed();chart->from=from->dateTime();chart->to=to->dateTime();int peak=0,samples=0,playing=0;for(auto value:chart->samples){auto sample=value.toObject();if(sample["source"].toString()!=chart->source)continue;auto time=QDateTime::fromSecsSinceEpoch(sample["time"].toDouble(),QTimeZone::UTC);if(time<chart->from||time>chart->to)continue;if(sample.contains("connections")){++samples;peak=qMax(peak,sample["connections"].toInt());}playing+=sample["playingSeconds"].toInt();}summary->setText(QString("Peak connections: %1 · Recorded audience minutes: %2\nObserved playout: approximately %3 min (10-second samples)").arg(samples?QString::number(peak):"—").arg(samples).arg(playing/60.,0,'f',1));chart->update();};
    auto range=[=]{auto now=QDateTime::currentDateTimeUtc();auto start=QDateTime(now.date(),QTime(0,0),QTimeZone::UTC);auto end=now;if(period->currentIndex()==1)start=start.addDays(1-start.date().dayOfWeek());else if(period->currentIndex()==2){end=QDateTime(QDate(now.date().year(),now.date().month(),1),QTime(0,0),QTimeZone::UTC);start=end.addMonths(-1);}if(period->currentIndex()!=3){QSignalBlocker a(from),b(to);from->setDateTime(start);to->setDateTime(end);}from->setEnabled(period->currentIndex()==3);to->setEnabled(period->currentIndex()==3);update();};QObject::connect(period,&QComboBox::currentIndexChanged,page,range);QObject::connect(from,&QDateTimeEdit::dateTimeChanged,page,update);QObject::connect(to,&QDateTimeEdit::dateTimeChanged,page,update);range();
    auto record=[=](int connections){auto now=QDateTime::currentDateTimeUtc().toSecsSinceEpoch();QJsonObject sample{{"source",url->text().trimmed()+"|"+path->text().trimmed()},{"time",double(now-now%60)},{"playingSeconds",play->state()==Playout::Playing?10:0}};if(connections>=0)sample["connections"]=connections;if(!chart->samples.isEmpty()&&chart->samples.last().toObject()["time"]==sample["time"]&&chart->samples.last().toObject()["source"]==sample["source"]){auto prior=chart->samples.last().toObject();sample["playingSeconds"]=qMin(60,prior["playingSeconds"].toInt()+sample["playingSeconds"].toInt());if(prior.contains("connections"))sample["connections"]=qMax(prior["connections"].toInt(),connections);chart->samples.removeLast();}chart->samples.append(sample);while(!chart->samples.isEmpty()&&chart->samples.first().toObject()["time"].toDouble()<now-63*86400)chart->samples.removeFirst();QSaveFile save(historyFile);if(save.open(QIODevice::WriteOnly)){save.write(QJsonDocument(chart->samples).toJson(QJsonDocument::Compact));save.commit();}range();};
    QObject::connect(url,&QLineEdit::textChanged,page,update);QObject::connect(path,&QLineEdit::textChanged,page,update);auto generation=std::make_shared<int>(0);auto *network=new QNetworkAccessManager(page);auto busy=std::make_shared<bool>(false);auto poll=[=]{if(*busy)return;if(!connectButton->isChecked()){record(-1);return;}QUrl endpoint(url->text());if(!endpoint.isValid()||(endpoint.scheme()!="http"&&endpoint.scheme()!="https")){status->setText("Enter an HTTP or HTTPS metrics URL.");connectButton->setChecked(false);return;}*busy=true;const int requestGeneration=*generation;QNetworkRequest request(endpoint);request.setTransferTimeout(5000);auto *reply=network->get(request);QObject::connect(reply,&QNetworkReply::finished,page,[=]{*busy=false;if(requestGeneration!=*generation||!connectButton->isChecked()){reply->deleteLater();return;}if(reply->error()!=QNetworkReply::NoError){count->setText("Audience data unavailable");status->setText(reply->errorString());record(-1);}else {int readers=0;bool recognized=false;const QString wanted=path->text().trimmed();const auto body=QString::fromUtf8(reply->readAll());const auto lines=body.split('\n');for(const auto &line:lines){if(!line.startsWith("paths_readers{")&&!line.startsWith("hls_sessions{"))continue;recognized=true;const auto marker=line.startsWith("hls_sessions{")?"path":"name";QRegularExpression re(QString("%1=\"([^\"]*)\"").arg(marker));if(re.match(line).captured(1)!=wanted)continue;if(line.contains("readerType=\"hlsMuxer\""))continue;bool ok=false;double value=line.section(' ',-1).toDouble(&ok);if(ok)readers+=qMax(0,int(value));}if(!recognized&&!body.contains("paths{")&&!body.contains("# Paths")&&!body.contains("hls_muxers")){count->setText("Audience data unavailable");status->setText("This endpoint did not return MediaMTX metrics.");record(-1);}else {status->setText("Connected · last update "+QDateTime::currentDateTimeUtc().toString("HH:mm:ss 'UTC'"));count->setText(QString("%1 receiver connections").arg(readers));record(readers);}}reply->deleteLater();});};
    auto *timer=new QTimer(page);timer->setInterval(10000);QObject::connect(timer,&QTimer::timeout,page,poll);timer->start();QObject::connect(connectButton,&QPushButton::toggled,page,[=](bool on){++*generation;url->setEnabled(!on);path->setEnabled(!on);connectButton->setText(on?"Disconnect metrics":"Connect metrics");QSettings().setValue("monitor/url",url->text());QSettings().setValue("monitor/path",path->text());if(on)poll();else count->setText("Audience source disconnected");});
    auto *receiver=new QProcess(page);receiver->setProcessChannelMode(QProcess::MergedChannels);QObject::connect(local,&QPushButton::clicked,page,[=]{if(receiver->state()!=QProcess::NotRunning){receiver->terminate();return;}const auto executable=QCoreApplication::applicationDirPath()+"/../tools/mediamtx/mediamtx.exe";if(!QFileInfo::exists(executable)){status->setText("The local MediaMTX receiver is missing from tools/mediamtx.");return;}QFile config(directory+"/local-receiver.yml");if(!config.open(QIODevice::WriteOnly)){status->setText(config.errorString());return;}config.write("logLevel: info\nreadTimeout: 30s\nwriteTimeout: 30s\nrtsp: no\nwebrtc: no\nmoq: no\nrtmp: yes\nrtmpAddress: 127.0.0.1:1935\nsrt: yes\nsrtAddress: 127.0.0.1:8890\nhls: yes\nhlsAddress: 127.0.0.1:8888\nmetrics: yes\nmetricsAddress: 127.0.0.1:9998\npaths:\n  cuebase:\n");config.close();receiver->start(executable,{config.fileName()});});QObject::connect(receiver,&QProcess::started,page,[=]{local->setText("Stop local test receiver");status->setText("Local receiver started. Publish using either destination above.");});QObject::connect(receiver,&QProcess::readyRead,page,[=]{const auto text=QString::fromUtf8(receiver->readAll());if(text.contains("ERR"))status->setText(text.right(600));});QObject::connect(receiver,&QProcess::finished,page,[=]{local->setText("Start local test receiver");});QObject::connect(qApp,&QCoreApplication::aboutToQuit,receiver,[=]{if(receiver->state()!=QProcess::NotRunning){receiver->terminate();if(!receiver->waitForFinished(1000))receiver->kill();}});return page;
}
